package sauna_test

import (
	"encoding/json"
	"reflect"
	"testing"

	"example.com/saunabook/sauna"
)

const casesExJSON = `[{"Minutes": 45, "StartHour": 18, "Members": 4, "Guests": 0, "Towels": false}, {"Minutes": 45, "StartHour": 15, "Members": 1, "Guests": 0, "Towels": true}, {"Minutes": 15, "StartHour": 9, "Members": 4, "Guests": 1, "Towels": false}, {"Minutes": 0, "StartHour": 6, "Members": 4, "Guests": 3, "Towels": false}]`

type outcomeEx struct {
	Value *sauna.Receipt `json:"value,omitempty"`
	Err   string `json:"err,omitempty"`
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var cases []sauna.Booking
	if err := json.Unmarshal([]byte(casesExJSON), &cases); err != nil {
		panic(err)
	}
	var out []any
	for _, c := range cases {
		res, err := sauna.Charge(c)
		var o outcomeEx
		if err != nil {
			o.Err = err.Error()
		} else {
			o.Value = &res
		}
		b, _ := json.Marshal(o)
		var v any
		_ = json.Unmarshal(b, &v)
		out = append(out, normEx(v))
	}
	return out
}

const wantExJSON = `[{"value": {"Cents": 900, "Lines": ["3 blocks x 300"]}}, {"value": {"Cents": 815, "Lines": ["3 blocks x 300", "off-peak: -225", "towels x1: +140"]}}, {"value": {"Cents": 300, "Lines": ["1 blocks x 300", "off-peak: -75", "minimum charge applied"]}}, {"err": "a session is 15..120 minutes in steps of 15, got 0"}]`

func TestExRecorded(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantExJSON), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d outcomes, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("case %d: got %v, want %v", i, got[i], w)
		}
	}
}

