final class FlexTicketRule implements TicketRule {
    @Override
    public int cents(int priceCents, int daysBefore) {
        int cents;
        int base = 125;
        if (priceCents > 700) {
            base += 4 * (priceCents / 10);
        }
        cents = base;
        return cents;
    }
}

