import json
import unittest

import importlib, itertools
MOD = "meters.desk"

def drive(ops, call, advance):
    results = []
    for op in ops:
        name, args = op[0], op[1:]
        if name == "advance":
            advance(args[0])
            continue
        args = [results[a["ref"]] if isinstance(a, dict) and "ref" in a else a for a in args]
        try:
            res = call(name, *args)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return results


class FakeClock:
    def __init__(self, t0):
        self.now = t0

    def time(self):
        return self.now

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds

def run_case(case):
    mod = importlib.import_module(MOD)
    clock = FakeClock(case["t0"])
    notes, ids = [], itertools.count(1000)
    desk = mod.MeterDesk(rates={"D": 130, "E": 50, "B": 190}, clock=clock, new_id=lambda: next(ids), notify=notes.append)
    results = drive(case["ops"], lambda n, *a: getattr(desk, n)(*a), clock.advance)
    return {"results": results, "notes": notes}

def norm(x):
    return json.loads(json.dumps(x))


class MeterDeskTests(unittest.TestCase):
    def test_scenario_1(self):
        case = json.loads("{\"t0\": 1000000, \"ops\": [[\"start_session\", \"ZZ-1\", \"B\"], [\"advance\", 240], [\"start_session\", \"AB-32\", \"E\"], [\"stop_session\", {\"ref\": 0}], [\"open_sessions\"]]}")
