        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1000, 100, {\"raises\": \"KeyError\"}, 1001, [\"AB-19\"]], \"notes\": [\"receipt 1000: AB-22 zone E 0 min -> 100\"]}"))

    def test_scenario_3(self):
        case = json.loads("{\"t0\": 1000000, \"ops\": [[\"start_session\", \"AB-27\", \"B\"], [\"stop_session\", {\"ref\": 0}], [\"stop_session\", {\"ref\": 0}], [\"start_session\", \"ZZ-1\", \"B\"], [\"start_session\", \"ZZ-1\", \"B\"], [\"start_session\", \"ZZ-1\", \"B\"], [\"stop_session\", {\"ref\": 5}], [\"start_session\", \"ZZ-1\", \"B\"], [\"advance\", 900], [\"start_session\", \"ZZ-1\", \"D\"], [\"start_session\", \"ZZ-1\", \"D\"], [\"open_sessions\"]]}")
