import json
import unittest

from pantry import Recipe, shopping_list
from pantry import cli, sections, shopping, units


def run_case(case):
    recipes = [Recipe(n, s, rows) for n, s, rows in case["recipes"]]
    return {
        "with_stock": shopping_list(recipes, case["stock"]),
        "plain": shopping_list(recipes),
        "scaled": [r.scale(case["servings"]).describe() for r in recipes],
        "grams": [r.total_grams() for r in recipes],
        "stock": shopping.describe_stock(case["stock"]),
        "cli": cli.main([str(case["servings"])]),
        "back": units.from_grams(case["g"], case["unit"]),
        "sections": [sections.section_dairy("x"), sections.section_dry("y"), sections.section_produce("z")],
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"recipes\": [], \"stock\": {\"leek\": 10, \"rice\": 500}, \"servings\": 3, \"g\": 2500, \"unit\": \"kg\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"with_stock\": [], \"plain\": [], \"scaled\": [], \"grams\": [], \"stock\": \"leek: 10 g\\nrice: 500 g\", \"cli\": [[\"A-dairy:milk\", 360], [\"C-dry:oats\", 120]], \"back\": 2.5, \"sections\": [\"A-dairy:x\", \"C-dry:y\", \"B-produce:z\"]}"))

    def test_example_2(self):
        case = json.loads("{\"recipes\": [[\"dish0\", 4, [[\"milk\", 3, \"tbsp\", \"dairy\"], [\"leek\", 0.5, \"oz\", \"produce\"]]], [\"dish1\", 4, [[\"butter\", 3, \"tbsp\", \"dairy\"]]], [\"dish2\", 2, [[\"leek\", 2, \"cup\", \"produce\"], [\"leek\", 0.5, \"oz\", \"produce\"]]]], \"stock\": {\"milk\": 10, \"leek\": 500}, \"servings\": 1, \"g\": 999, \"unit\": \"cup\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"with_stock\": [[\"A-dairy:butter\", 45], [\"A-dairy:milk\", 35], [\"B-produce:leek\", 8]], \"plain\": [[\"A-dairy:butter\", 45], [\"A-dairy:milk\", 45], [\"B-produce:leek\", 508]], \"scaled\": [\"dish0 for 1: 0.75 tbsp milk, 0.12 oz leek\", \"dish1 for 1: 0.75 tbsp butter\", \"dish2 for 1: 1 cup leek, 0.25 oz leek\"], \"grams\": [59, 45, 494], \"stock\": \"leek: 500 g\\nmilk: 10 g\", \"cli\": [[\"A-dairy:milk\", 120], [\"C-dry:oats\", 40]], \"back\": 4.2, \"sections\": [\"A-dairy:x\", \"C-dry:y\", \"B-produce:z\"]}"))

    def test_example_3(self):
        case = json.loads("{\"recipes\": [[\"dish0\", 4, [[\"cream\", 3, \"lb\", \"dairy\"], [\"rice\", 250, \"lb\", \"dry\"], [\"cream\", 3, \"g\", \"dairy\"], [\"apple\", 2, \"cup\", \"produce\"]]]], \"stock\": {}, \"servings\": 1, \"g\": 100, \"unit\": \"kg\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"with_stock\": [[\"A-dairy:cream\", 1365], [\"B-produce:apple\", 480], [\"C-dry:rice\", 113500]], \"plain\": [[\"A-dairy:cream\", 1365], [\"B-produce:apple\", 480], [\"C-dry:rice\", 113500]], \"scaled\": [\"dish0 for 1: 0.75 lb cream, 62.5 lb rice, 0.75 g cream, 0.5 cup apple\"], \"grams\": [115345], \"stock\": \"\", \"cli\": [[\"A-dairy:milk\", 120], [\"C-dry:oats\", 40]], \"back\": 0.1, \"sections\": [\"A-dairy:x\", \"C-dry:y\", \"B-produce:z\"]}"))


if __name__ == '__main__':
    unittest.main()

