"""Key-value stores."""


class _Memory:
    """The dictionary and the read counter."""

    def __init__(self):
        self.data = {}
        self.reads = 0

    def get(self, key, default=None):
        self.reads += 1
        return self.data.get(key, default)

    def put(self, key, value):
        self.data[key] = value

    def delete(self, key):
        return self.data.pop(key, None)


class Store:
    """In-memory store with get, put and delete."""

    def __init__(self):
        self._mem = _Memory()
        self.data = self._mem.data

    @property
    def reads(self):
        return self._mem.reads

    def get(self, key, default=None):
        return self._mem.get(key, default)

    def put(self, key, value):
        self._mem.put(key, value)

    def delete(self, key):
        return self._mem.delete(key)


class AuditedStore:
    """Remembers every change in `log`."""

    def __init__(self):
        self._mem = _Memory()
        self.data = self._mem.data
        self.log = []

    @property
    def reads(self):
        return self._mem.reads

    def get(self, key, default=None):
        return self._mem.get(key, default)

    def put(self, key, value):
        self.log.append(("put", key))
        self._mem.put(key, value)

    def delete(self, key):
        self.log.append(("delete", key))
        return self._mem.delete(key)


class QuotaStore:
    """Refuses new keys beyond `max_keys`."""

    def __init__(self, max_keys):
        self._mem = _Memory()
        self.data = self._mem.data
        self.log = []
        self.max_keys = max_keys

    @property
    def reads(self):
        return self._mem.reads

    def get(self, key, default=None):
        return self._mem.get(key, default)

    def put(self, key, value):
        if key not in self.data and len(self.data) >= self.max_keys:
            raise KeyError("quota of %d keys reached" % self.max_keys)
        self.log.append(("put", key))
        self._mem.put(key, value)

    def delete(self, key):
        self.log.append(("delete", key))
        return self._mem.delete(key)


class ExpiringStore:
    """Entries live for `ttl` ticks; call tick() to advance the clock."""

    def __init__(self, max_keys, ttl):
        self._mem = _Memory()
        self.data = self._mem.data
        self.log = []
        self.max_keys = max_keys
        self.ttl = ttl
        self.now = 0
        self.born = {}

    @property
    def reads(self):
        return self._mem.reads

    def get(self, key, default=None):
        if key in self.born and self.now - self.born[key] >= self.ttl:
            self.delete(key)
        return self._mem.get(key, default)

    def put(self, key, value):
        if key not in self.data and len(self.data) >= self.max_keys:
            raise KeyError("quota of %d keys reached" % self.max_keys)
        self.log.append(("put", key))
        self._mem.put(key, value)
        self.born[key] = self.now

    def delete(self, key):
        self.born.pop(key, None)
        self.log.append(("delete", key))
        return self._mem.delete(key)

    def tick(self, n=1):
        self.now += n

