"""Stock items."""
import warnings
from . import weights


class StockItem:
    """A line of stock: sku, quantity in grams and a price per kilogram in cents."""

    def __init__(self, sku, qty, unit, price_cents):
        self.sku = sku
        self.grams = weights.to_base(qty, unit)
        self.price_cents = price_cents

    def worth(self, *args, **kwargs):
        """Deprecated alias of value_cents()."""
        warnings.warn("StockItem.worth is deprecated, use value_cents", DeprecationWarning, stacklevel=2)
        return self.value_cents(*args, **kwargs)

    def value_cents(self):
        """Value of the line in cents."""
        return self.grams * self.price_cents // 1000

    def label(self):
        return "%s (%s)" % (self.sku, weights.pretty(self.grams))


def make_item(row):
    """Build an item from a (sku, qty, unit, price_cents) row."""
    sku, qty, unit, price = row
    return StockItem(sku, qty, unit, price)

solution.stockroom/pricing.py:
"""Pricing rules."""
import warnings
from .items import StockItem
from .weights import to_base


def bulk_discount(grams):
    """Percent off for big lines."""
    if grams >= to_base(10, "kg"):
        return 10
    if grams >= to_base(2, "kg"):
        return 5
    return 0


def quote_cents(item, extra_discount=0):
    """Price of an item in cents after the bulk discount and an optional extra discount in percent."""
    if not isinstance(item, StockItem):
        raise TypeError("expected a StockItem")
    pct = min(100, bulk_discount(item.grams) + extra_discount)
    return item.value_cents() * (100 - pct) // 100


def calc_price(*args, **kwargs):
    """Deprecated alias of quote_cents."""
    warnings.warn("calc_price is deprecated, use quote_cents", DeprecationWarning, stacklevel=2)
    return quote_cents(*args, **kwargs)

solution.stockroom/report.py:
"""Text reports."""
import warnings
import stockroom.weights as u

from .items import StockItem
from .pricing import quote_cents


def render(items, header=True, **legacy):
    """Fixed-width table of the items with their prices."""
    if "with_header" in legacy:
        warnings.warn("with_header is deprecated, use header", DeprecationWarning, stacklevel=2)
        header = legacy.pop("with_header")
    if legacy:
        raise TypeError("unexpected keyword arguments: " + ", ".join(sorted(legacy)))
    lines = ["sku                qty      price"] if header else []
    for it in items:
        lines.append("%-14s %8s %9d" % (it.sku, u.pretty(it.grams), quote_cents(it)))
    return "\n".join(lines)


def summarize(items):
    """Counts and money totals for a list of items."""
    value = sum(it.value_cents() for it in items if isinstance(it, StockItem))
    priced = sum(quote_cents(it) for it in items)
    return {"count": len(items), "value": value, "after_discount": priced, "saved": value - priced, "weight": u.pretty(sum(it.grams for it in items))}

