import json
import unittest

from stockroom import cli, items as items_mod, pricing, report, units
from stockroom.items import StockItem


def run_case(case):
    its = [items_mod.make_item(tuple(r)) for r in case["rows"]]
    direct = StockItem("Z9", case["qty"], case["unit"], case["price"])
    return {
        "labels": [i.label() for i in its],
        "worth": [i.worth() for i in its],
        "direct": [direct.worth(), pricing.calc_price(direct, case["extra"])],
        "prices": [pricing.calc_price(i) for i in its],
        "render": [report.render(its), report.render(its, with_header=False)],
        "summary": report.summarize(its),
        "cli": cli.main(case["argv"]),
        "pretty": units.pretty(case["grams"]),
        "base": units.to_base(case["qty"], case["unit"]),
        "isitem": isinstance(direct, items_mod.StockItem),
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"rows\": [[\"B68\", 0.5, \"oz\", 515], [\"D40\", 1, \"lb\", 2351], [\"D63\", 1, \"lb\", 2266]], \"qty\": 2, \"unit\": \"kg\", \"price\": 2827, \"extra\": 5, \"argv\": [\"B68:0.5:oz:515\", \"D40:1:lb:2351\", \"D63:1:lb:2266\"], \"grams\": 15}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"labels\": [\"B68 (14 g)\", \"D40 (454 g)\", \"D63 (454 g)\"], \"worth\": [7, 1067, 1028], \"direct\": [5654, 5088], \"prices\": [7, 1067, 1028], \"render\": [\"sku                qty      price\\nB68                14 g         7\\nD40               454 g      1067\\nD63               454 g      1028\", \"B68                14 g         7\\nD40               454 g      1067\\nD63               454 g      1028\"], \"summary\": {\"count\": 3, \"value\": 2102, \"after_discount\": 2102, \"saved\": 0, \"weight\": \"922 g\"}, \"cli\": {\"text\": \"sku                qty      price\\nB68                14 g         7\\nD40               454 g      1067\\nD63               454 g      1028\", \"summary\": {\"count\": 3, \"value\": 2102, \"after_discount\": 2102, \"saved\": 0, \"weight\": \"922 g\"}, \"cheapest\": \"B68\"}, \"pretty\": \"15 g\", \"base\": 2000, \"isitem\": true}"))

    def test_example_2(self):
        case = json.loads("{\"rows\": [[\"D71\", 40, \"oz\", 1538]], \"qty\": 3, \"unit\": \"oz\", \"price\": 2872, \"extra\": 5, \"argv\": [\"D71:40:oz:1538\"], \"grams\": 15}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"labels\": [\"D71 (1.12 kg)\"], \"worth\": [1722], \"direct\": [241, 228], \"prices\": [1722], \"render\": [\"sku                qty      price\\nD71             1.12 kg      1722\", \"D71             1.12 kg      1722\"], \"summary\": {\"count\": 1, \"value\": 1722, \"after_discount\": 1722, \"saved\": 0, \"weight\": \"1.12 kg\"}, \"cli\": {\"text\": \"sku                qty      price\\nD71             1.12 kg      1722\", \"summary\": {\"count\": 1, \"value\": 1722, \"after_discount\": 1722, \"saved\": 0, \"weight\": \"1.12 kg\"}, \"cheapest\": \"D71\"}, \"pretty\": \"15 g\", \"base\": 84, \"isitem\": true}"))

    def test_example_3(self):
        case = json.loads("{\"rows\": [[\"A46\", 40, \"oz\", 1884], [\"C88\", 12, \"kg\", 1229], [\"E33\", 0.5, \"lb\", 661]], \"qty\": 2, \"unit\": \"g\", \"price\": 2586, \"extra\": 5, \"argv\": [\"A46:40:oz:1884\", \"C88:12:kg:1229\", \"E33:0.5:lb:661\"], \"grams\": 1000}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"labels\": [\"A46 (1.12 kg)\", \"C88 (12.00 kg)\", \"E33 (227 g)\"], \"worth\": [2110, 14748, 150], \"direct\": [5, 4], \"prices\": [2110, 13273, 150], \"render\": [\"sku                qty      price\\nA46             1.12 kg      2110\\nC88            12.00 kg     13273\\nE33               227 g       150\", \"A46             1.12 kg      2110\\nC88            12.00 kg     13273\\nE33               227 g       150\"], \"summary\": {\"count\": 3, \"value\": 17008, \"after_discount\": 15533, \"saved\": 1475, \"weight\": \"13.35 kg\"}, \"cli\": {\"text\": \"sku                qty      price\\nA46             1.12 kg      2110\\nC88            12.00 kg     13273\\nE33               227 g       150\", \"summary\": {\"count\": 3, \"value\": 17008, \"after_discount\": 15533, \"saved\": 1475, \"weight\": \"13.35 kg\"}, \"cheapest\": \"E33\"}, \"pretty\": \"1.00 kg\", \"base\": 2, \"isitem\": true}"))


